package usecase

import (
	"encoding/json"
	"fmt"
	"path/filepath"

	"github.com/Frank5ive/goforge/internal/domain"
)

// readManifest returns the project's .goforge.json, and false if it has none
// (e.g. a project generated by an older GoForge).
func readManifest(w domain.FileWriter, projectDir string) (domain.Manifest, bool, error) {
	path := filepath.Join(projectDir, domain.ManifestFile)
	if !w.FileExists(path) {
		return domain.Manifest{}, false, nil
	}

	content, err := w.ReadFile(path)
	if err != nil {
		return domain.Manifest{}, false, err
	}

	var m domain.Manifest
	if err := json.Unmarshal([]byte(content), &m); err != nil {
		return domain.Manifest{}, false, fmt.Errorf("%s is not valid JSON: %w", domain.ManifestFile, err)
	}
	return m, true, nil
}

// writeManifest writes m to the project's .goforge.json.
func writeManifest(w domain.FileWriter, projectDir string, m domain.Manifest) error {
	content, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return w.WriteFile(filepath.Join(projectDir, domain.ManifestFile), string(content)+"\n")
}
